mod solution;

fn main() {
    let cases = [
    (r#"[2,3,7,11,15]"#, r#"1,5"#),
    (r#"[1,8,9]"#, r#"2,3"#),
    (r#"
[1,8,9]
"#, r#"2,3"#),
    (r#"  
[2,3,7,11,15]
  "#, r#"1,5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS sorted-two-sum");
}
